// src/jsx/Contacts.jsx
import useSearchUsers from "../hooks/useSearchUsers";
import { useEffect, useState } from "react";
import { collection, query, onSnapshot } from "firebase/firestore";
import Avatar from "./Avatar";
import { db } from "../js/firebaseConfig";
import { doc, setDoc, serverTimestamp, getDoc } from "firebase/firestore";

async function createRoom(currentUser, otherUser) {
    const roomId = [currentUser.uid, otherUser.id].sort().join("_");
    const roomRef = doc(db, "rooms", roomId);
    const snap = await getDoc(roomRef);

    if (!snap.exists()) {
        await setDoc(roomRef, {
            id: roomId,
            members: [currentUser.uid, otherUser.id],
            createdAt: serverTimestamp(),
            lastMessage: "",
            lastUpdated: serverTimestamp()
        });
    }

    return roomId;
}

export default function Contacts({ currentUser, setChatUser, setChatGroup, setScreen, logout }) {
    const { allUsers, filtered, search, searchUsers } = useSearchUsers();
    const [groups, setGroups] = useState([]);

    useEffect(() => {
        const q = query(collection(db, "groups"));
        const unsub = onSnapshot(q, snap => {
            setGroups(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        });
        return () => unsub();
    }, []);

    if (!currentUser) return <div>Carregando...</div>;

    const list = filtered && filtered.length ? filtered : allUsers || [];

    const usersToShow = list.filter(u => u && u.id && u.id !== currentUser.uid);

    return (
        <div className="sidebar">
            <div className="sidebar-header">
                <span>Bem-vindo, {currentUser.email || "Usuário"}</span>
                <button className="logout-btn" onClick={logout}>Sair</button>
            </div>

            <div className="sidebar-search">
                <input
                    placeholder="Pesquisar contatos..."
                    value={search}
                    onChange={e => searchUsers(e.target.value)}
                />
            </div>

            <h3 className="section-title">Usuários</h3>

            {usersToShow.map(u => (
                <div
                    key={u.id}
                    className="contact-item"
                    onClick={() => {
                        setChatUser(u);
                        setChatGroup(null);
                        setScreen("private");
                    }}
                    style={{ display: "flex", alignItems: "center", gap: 12 }}
                >
                    <Avatar user={u} size={44} />
                    <div style={{ flex: 1 }}>
                        <div className="contact-name" style={{ fontWeight: 600 }}>
                            {u.nome || u.email || "Usuário sem nome"}
                        </div>
                        <div style={{ fontSize: 12, color: "#666" }}>
                            {u.email || "Sem email"}
                        </div>
                    </div>
                </div>
            ))}

            <button
                className="create-group-btn"
                onClick={() => setScreen("createGroup")}
            >
                + Criar Grupo
            </button>

        </div>
    );
}
